sp_widget.client_script:
function($rootScope, $scope, $timeout, $location, $log, $window, spUtil, nowAttachmentHandler, spAriaUtil, spNavStateManager) {
	var c=this;

	c.data.action="";
	// Collaborator Information vars
	/*
	$scope.collaborator = "";
	$scope.review_date = "";
	$scope.job_conpany = "";
	$scope.job_department = "";
	$scope.job_title = "";
	$scope.job_commitment_date = "";

	// Collaborator satisfaction vars
	$scope.collaborator_work_environment = "";
	$scope.collaborator_workload = "";
	$scope.collaborator_work_atmosphere_climate = "";
	$scope.collaborator_team_spirit = "";
	$scope.collaborator_relationship_manager = "";
	$scope.collaborator_general_motivation = "";

	// Manager evaluation vars
	$scope.manager_effectiveness_and_efficiency = "";
	$scope.manager_customer_satisfaction = "";
	$scope.manager_cooperation_helpfulness = "";
	$scope.manager_identification_institution = "";
	$scope.manager_vision = ""; 
	$scope.manager_solution_oriented_proactive = "";
	$scope.manager_leadership_na = "";
	$scope.other_manager_evaluation_1 = "";
	$scope.other_manager_evaluation_2 = "";

	// Objective or measure var
	$scope.textarea_ea_review_objective_or_measure = "";

	// Desire for training and professional development var
	$scope.textarea_ea_training_and_professional_development = "";

	// Remarks comments var
	$scope.textarea_ea_remarks_comments = "";
	*/

	$scope.triggerOnSubmit = function () {
		//spUtil.addTrivialMessage(c.data);
		c.data.action="updateReview";
		c.server.update().then(function(){
			c.data.action="";
		});
	}

	$rootScope.$on('selectReview', function(event,name) {
		c.data.table = $rootScope.reviewTable;
		c.data.sys_id = $rootScope.reviewID;
		c.data.action = "selectReview";
		c.server.get({
			table : $rootScope.reviewTable,
			sys_id : $rootScope.reviewID,
			action : "selectReview"
		}).then(function(r){
			c.data = r.data;
			var fields = r.data.f._fields
			$scope.hasSelected = r.data.hasSelected;
			setVarsValues(fields);
			disableFields();
		});
	})

	function disableFields() {
		var fieldsets = document.getElementsByTagName("fieldset");
		for (var i=0; i < fieldsets.length; i++) {
			fieldset = fieldsets[i];
			if(c.data.isDisabled) {
				fieldset.setAttribute("disabled", "true");
			}
			else {
				fieldset.removeAttribute("disabled");
			}
		}
	}

	$('#datetimepicker').datepicker({
		format: "dd.mm.yyyy", 
		endDate: "+3m",
		todayBtn: "linked",
		calendarWeeks: true,
		autoclose: true,
		language: "fr",
		todayHighlight: true
	});

	function setVarsValues (f) {
		c.data.review_state = f.review_state.value;
		c.data.isDisabled = f.review_state.value =='completed' ? true : false;
		// Collaborator Information vars
		c.data.collaborator = f.collaborator.displayValue;
		c.data.job_company = f.job_company.displayValue;
		c.data.job_department = f.job_department.displayValue;
		c.data.job_title = f.job_title.displayValue;
		c.data.job_commitment_date = f.job_commitment_date.displayValue;

		var sDate = f.review_date.displayValue+'';
		var sToday = c.data.review_date_default;
		if(!sDate) {
			sDate = sToday;
		}
		c.data.review_date = sDate;
		$('#datetimepicker').datepicker('setDate',sDate);
		//$('#datetimepicker').datepicker('setStartDate',sDate);

		// Collaborator satisfaction vars
		c.data.collaborator_work_environment = f.collaborator_work_environment.value;
		c.data.collaborator_workload = f.collaborator_workload.value;
		c.data.collaborator_work_atmosphere_climate = f.collaborator_work_atmosphere_climate.value;
		c.data.collaborator_team_spirit = f.collaborator_team_spirit.value;
		c.data.collaborator_relationship_manager = f.collaborator_relationship_manager.value;
		c.data.collaborator_general_motivation = f.collaborator_general_motivation.value;

		// Manager evaluation vars
		c.data.manager_effectiveness_and_efficiency = f.manager_effectiveness_and_efficiency.value;
		c.data.manager_customer_satisfaction = f.manager_customer_satisfaction.value;
		c.data.manager_cooperation_helpfulness = f.manager_cooperation_helpfulness.value;
		c.data.manager_identification_institution = f.manager_identification_institution.value;
		c.data.manager_vision = f.manager_vision.value; 
		c.data.manager_solution_oriented_proactive = f.manager_solution_oriented_proactive.value;
		c.data.manager_leadership_na = f.manager_leadership_na.value;
		c.data.other_manager_evaluation_1 = f.other_manager_evaluation_1.value;
		c.data.other_manager_evaluation_2 = f.other_manager_evaluation_2.value;

		// Objective or measure var
		c.data.review_objective_or_meausre = f.review_objective_or_meausre.value;

		// Desire for training and professional development var
		c.data.training_and_professional_development = f.training_and_professional_development.value;

		// Remarks comments var
		c.data.remarks_comments = f.remarks_comments.value;
	}

	function getToday() {
		var today = new Date();
		var yyyy = today.getFullYear();
		var mm = today.getMonth() + 1; // Months start at 0!
		var dd = today.getDate();

		if (dd < 10) dd = '0' + dd;
		if (mm < 10) mm = '0' + mm;

		var result = dd + '/' + mm + '/' + yyyy;
		return result;
	}

	/*
	if(c.data.table) {
				$('#datetimepicker').datepicker({
				format: "dd.mm.yyyy",
				startDate: "+0d",                
				endDate: "+3m",
				todayBtn: "linked",
				calendarWeeks: true,
				todayHighlight: true,
				autoclose: true,
				language: "fr"
			});
	}
	*/
}

sp_widget.css:
.btn-form-menu {
  vertical-align: inherit;
  padding: inherit;
  background: none;
}

.panel-title {
  word-wrap: break-word;
}

.panel-heading {
  .dropdown-menu {
    a {
      white-space: normal;
    }
  }
}

.panel-default {
  padding: 2.4rem;
  box-shadow: 0 .4rem .8rem 0 rgba(23, 40, 52, .08);
  border: none;
}

.wrapper-md {
  padding-left: 0px !important;
}

input[type="text"] {
  margin-bottom: 1.6rem;
}
/*********************************** radio butt0n ***********************************/
.form-group {
  margin-bottom:.25rem;
}

.layout {
  display:flex;
  flex-direction: row;
  padding-left: 30px;
  padding-right: 20px;
}

*,
*:after,
*:before {
  box-sizing: border-box;
}

$primary-color: #00005c; // Change color here. C'mon, try it! 
$text-color: mix(#000, $brand-primary, 64%);

body {

  font-size: calc(1em + 1.25vw);

  color: #181A1F;
  font-family: "Lato", sans-serif;
  font-size: 1.6rem;
  background: radial-gradient(at right bottom, #f8f6f6 6.56%, #f8f6f6 11.16%, #f8f6f6 17.26%, #f8f6f6 22.64%, #f8f6f6 42.58%);

}

.main {
  flex: 1 0 auto;
  min-height: calc(-515.49px + 100vh);
}

.sp-form-container {
  margin-bottom : 1em;
}

.radio {
  display: flex;
  flex-direction: row;
  margin-top: 5px;
  margin-bottom: 5px;
  width: 100%;
  justify-content: flex-end;
}

.radio label {
  display: flex;
  cursor: pointer;
  font-weight: 500;
  position: relative;
  overflow: hidden;
  margin-bottom: 0.175em;
  /* Accessible outline */
  /* Remove comment to use */ 
  /*
  &:focus-within {
  outline: .125em solid $primary-color;
}
  */

  input[type="radio"] {
    position: absolute;
    left: -9999px;
    &:checked + span {
      background-color: mix(#fff, $brand-primary, 84%);
      &:before {
        box-shadow: inset 0 0 0 0.4375em $brand-primary;
      }
    }
  }

  span {
    display: flex;
    align-items: center;
    padding: 0.375em 0.75em 0.375em 0.375em;
    border-radius: 99em; // or something higher...
    transition: 0.25s ease;

    &:hover {
      background-color: mix(#fff, $brand-primary, 84%);
    }

    &:before {
      display: flex;
      flex-shrink: 0;
      content: "";
      background-color: #fff;
      width: 1.25em;
      height: 1.25em;
      border-radius: 50%;
      margin-right: 0.375em;
      transition: 0.25s ease;
      box-shadow: inset 0 0 0 0.125em $brand-primary;
    }
  }
}

h4, .h4, h5, .h5, h6, .h6 {
  margin-top: 1.1rem;
  margin-bottom: 1.1rem;
}

h1, h2, h3, h4, h5, h6, .h1, .h2, .h3, .h4, .h5, .h6 {
  font-family: "Lato", sans-serif;
  font-weight: 600;
  line-height: 1.1;
  color: inherit;
}

/*********************************** input ***********************************/
:root {
  --input-focus-h: 245;
  --input-focus-s: 100%;
  --input-focus-l: 42%;
}

.input-group-addon {
  display: table-column;
  padding: .6rem 1.6rem;
  font-size: 1.6rem;
  font-weight: normal;
  line-height: 1;
  color: #181A1F;
  text-align: center;
  background-color: #f8f6f6;
  border: .1rem solid #8790A1;
  border-radius: .4rem;
}

.input {
  width:100%;
  font-size: 14px;
  // Capitalized to prevent Sass
  // thinking it's the Sass max()
  font-size: Max(14px, 1em);
  font-family: inherit;
  padding: 0.25em 0.5em;
  background-color: #fff;
  border: 1px solid $brand-primary;
  border-top: none;
  border-left: none;
  border-right: none;
  border-radius: 4px;
  transition: 180ms box-shadow ease-in-out;
}

.input:not(.disabled){
  &:focus{
    border-color: hsl(
      var(--input-focus-h),
      var(--input-focus-s),
      var(--input-focus-l)
    );
  /*
  box-shadow: 0 0 0 1px
  hsla(
  var(--input-focus-h),
  var(--input-focus-s),
  calc(var(--input-focus-l) + 40%),
  0.8
  );
  */
}
}

.input:not(textarea) {
  line-height: 1;
  height: 2.25rem;
}

[id^="textarea_ea_"] {
  margin-bottom:15px;
}

input[type="file"] {
  font-size: 0.9em;
  padding-top: 0.35rem;
}

textarea.input {
  resize: vertical;
}

.input[readonly] {
  border-style: dotted;
  cursor: not-allowed;
  color: #777;
}

.form-control[disabled] {
  background-color: #e6e8ea !important;
  background-image: none;
  border: 1px solid #bdc0c4;
  cursor: not-allowed;
}

label {
  font-size: 1.6rem;
  font-weight: 500;
  line-height: 1;
}

.input + label {
  margin-top: 2rem;
}

sp_widget.link:
function link(scope, element, attrs, controller) {

	$(document).ready(function(){

		$.fn.datepicker.dates['fr'] = {
			days: ["Dimanche", "Lundi", "Mardi", "Mercredi", "Jeudi", "Vendredi", "Samedi"],
			daysShort: ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"],
			daysMin: ["Di", "Lu", "Ma", "Me", "Je", "Ve", "Sa"],
			months: ["Janvier", "Février", "Mars", "Avril", "Mai", "Juin", "Juillet", "Août", "Septembre", "Octobre", "Novembre", "Décembre"],
			monthsShort: ["Jan", "Fév", "Mar", "Avr", "Mai", "Juin", "Juil", "Août", "Sept", "Oct", "Nov", "Dec"],
			today: "Aujourd'hui",
			clear: "Effcer",
			format: "dd.mm.yyyy",
			titleFormat: "MM yyyy", /* Leverages same syntax as 'format' */
			weekStart: 0
		};

		setTimeout(function(){

			var sToday = new Date().toJSON().slice(0, 10)
			$('#datetimepicker').datepicker({
				format: "dd.mm.yyyy", 
				endDate: "+3m",
				todayBtn: "linked",
				calendarWeeks: true,
				autoclose: true,
				language: "fr",
				todayHighlight: true
			});

		},300);

	});

}

sp_widget.script:
// form functionality - URL parameter driven
(function($sp, input, data, options, gs) {
	/*
		console.log("-------------------------------------------------------");
		console.log(input);
		console.log("-------------------------------------------------------");
	*/

	// populate the 'data' variable
	var currentDay = new GlideDate();
	data.review_date_default = currentDay.getDisplayValue();
	data.attachmentUploadSuccessMsg = gs.getMessage("Attachment upload was successful");
	data.recordAddedMsg = gs.getMessage("Record Added");
	data.updatedMsg = gs.getMessage("Record Updated");
	data.exportPDFMsg = gs.getMessage("Export to PDF");
	data.exportPDFLandMsg = gs.getMessage("Export to PDF (landscape)");
	data.addAttachmentMsg = gs.getMessage("Add an attachment");
	data.maxAttachmentSize = parseInt(gs.getProperty("com.glide.attachment.max_size", 1024));
	data.advancedUIEnabled = (gs.getProperty("glide.ui.advanced") == "true");
	data.closeWindowMsg = gs.getMessage("Close Window");
	if (isNaN(data.maxAttachmentSize))
		data.maxAttachmentSize = 24;
	data.largeAttachmentMsg = gs.getMessage("Attached files must be smaller than {0} - please try again", "" + data.maxAttachmentSize + "MB");

	if (input && input.action=="selectReview") {
		data.table = input.table;
		data.sys_id = input.sys_id;
		data.hasSelected=true;

		data.f = $sp.getForm(data.table, data.sys_id);

		/************************************* Collaborator Satisfaction ************************************/
		data.radio_collaborator_work_environment = getOptionItems("collaborator_work_environment");
		data.radio_collaborator_workload = getOptionItems("collaborator_workload");
		data.radio_collaborator_work_atmosphere_climate = getOptionItems("collaborator_work_atmosphere_climate");
		data.radio_collaborator_team_spirit = getOptionItems("collaborator_team_spirit");
		data.radio_collaborator_relationship_manager = getOptionItems("collaborator_relationship_manager");
		data.radio_collaborator_general_motivation = getOptionItems("collaborator_general_motivation");

		/**************************************** Manager Satisfaction **************************************/
		data.radio_manager_effectiveness_and_efficiency = getOptionItems("manager_effectiveness_and_efficiency");
		data.radio_manager_customer_satisfaction = getOptionItems("manager_customer_satisfaction");
		data.radio_manager_cooperation_helpfulness = getOptionItems("manager_cooperation_helpfulness");
		data.radio_manager_identification_institution = getOptionItems("manager_identification_institution");
		data.radio_manager_vision = getOptionItems("manager_vision");
		data.radio_manager_solution_oriented_proactive = getOptionItems("manager_solution_oriented_proactive");
		data.radio_manager_leadership_na = getOptionItems("manager_leadership_na");
		data.radio_other_manager_evaluation_2 = getOptionItems("other_manager_evaluation_2");
		data.radio_other_manager_evaluation_1 = getOptionItems("other_manager_evaluation_1");
		data.title_objective_measure = getOptionItems("review_objective_or_meausre");
		data.title_training_and_professional_development = getOptionItems("training_and_professional_development");
		data.title_remarks_comments = getOptionItems("remarks_comments");
		data.collaborator_satisfaction = getOptionItems("collaborator_satisfaction");
		data.manager_evaluation = getOptionItems("manager_evaluation");

		/****************************************************************************************************/
	}
	else if(input && input.action=="updateReview") {
		var grReview = new GlideRecord("x_snc_createnotes_note");
		if (grReview.get(input.sys_id)) {

			// Review date
			grReview.review_date = input.review_date;
			var sDate = input.review_date+'';
			grReview.review_year = sDate.slice(-4);

			// Collaborator satisfaction vars
			grReview.collaborator_work_environment = input.collaborator_work_environment;
			grReview.collaborator_workload = input.collaborator_workload;
			grReview.collaborator_work_atmosphere_climate = input.collaborator_work_atmosphere_climate;
			grReview.collaborator_team_spirit = input.collaborator_team_spirit;
			grReview.collaborator_relationship_manager = input.collaborator_relationship_manager;
			grReview.collaborator_general_motivation = input.collaborator_general_motivation;

			// Manager evaluation vars
			grReview.manager_effectiveness_and_efficiency = input.manager_effectiveness_and_efficiency;
			grReview.manager_customer_satisfaction = input.manager_customer_satisfaction;
			grReview.manager_cooperation_helpfulness = input.manager_cooperation_helpfulness;
			grReview.manager_identification_institution = input.manager_identification_institution;
			grReview.manager_vision = input.manager_vision; 
			grReview.manager_solution_oriented_proactive = input.manager_solution_oriented_proactive;
			grReview.manager_leadership_na = input.manager_leadership_na;
			grReview.other_manager_evaluation_1 = input.other_manager_evaluation_1;
			grReview.other_manager_evaluation_2 = input.other_manager_evaluation_2;

			// Objective or measure var
			grReview.review_objective_or_meausre = input.review_objective_or_meausre;

			// Desire for training and professional development var
			grReview.training_and_professional_development = input.training_and_professional_development;

			// Remarks comments var
			grReview.remarks_comments = input.remarks_comments;

			// save updates
			grReview.update();
		}

	}
	else {
		data.hasSelected=false;
	}

	function getOptionItems(field) {
		var inData = [];
		var language = gs.getSession().getLanguage();
		var choices = GlideChoiceList.getChoiceList("x_snc_createnotes_note", field);
		var obj={};
		var grForLabels = new GlideRecord("x_snc_createnotes_note");

		inData.push(grForLabels.getElement(field).getLabelLang(language));
		inData.push(field);

		for (i = 0; i < choices.getSize(); i++){
			obj.value = choices.getChoice(i).getValue();
			obj.label = choices.getChoice(i).getLabel();
			inData.push(obj);
			obj={};
		}
		return inData;
	}

})($sp, input, data, options, gs);
